		if archIndex == -1 {
			return invalid()
		}
		arch, nvr = basename[archIndex+1:], basename[:archIndex]
	}
	if arch == "" || strings.ContainsAny(arch, "-./\\ \t\r\n") {
		return invalid()
	}

	relIndex := strings.LastIndex(nvr, "-")
	if relIndex == -1 {
		return invalid()
	}
	rel = nvr[relIndex+1:]
	nameVersion := nvr[:relIndex]
	verIndex := strings.LastIndex(nameVersion, "-")
	if verIndex == -1 {
		return invalid()
	}
	name, ver = nameVersion[:verIndex], nameVersion[verIndex+1:]
	if name == "" || ver == "" || strings.HasPrefix(name, "-") || strings.ContainsAny(name+ver+rel, "/\\ \t\r\n") || strings.ContainsAny(ver+rel, ":-") {
		return invalid()
	}
	if prefix, rest, hasEpoch := strings.Cut(name, ":"); hasEpoch {
		if prefix == "" || rest == "" || strings.Trim(prefix, "0123456789") != "" || strings.Contains(rest, ":") {
			return invalid()
		}
		epoch, name = prefix, rest
	}
	return name, ver, rel, epoch, arch, nil
}

