584	func (o *redhatBase) parseInstalledPackagesLine(line string) (*models.Package, *models.SrcPackage, error) {
585		switch fields := splitRPMQueryLine(line); len(fields) {
586		case 6, 7:
587			sp, err := func() (*models.SrcPackage, error) {
588				switch fields[5] {
589				case "(none)":
590					return nil, nil
591				default:
592					n, v, r, _, _, err := splitFileName(fields[5])
593					if err != nil {
594						o.warns = append(o.warns, xerrors.Errorf("Failed to parse source rpm file. err: %w", err))
595						return nil, nil
596					}
597					return &models.SrcPackage{
598						Name:        n,
599						Version:     rpmPackageVersion(fields[1], v, r),
600						Arch:        "src",
601						BinaryNames: []string{fields[0]},
602					}, nil
603				}
604			}()
605			if err != nil {
606				return nil, nil, xerrors.Errorf("Failed to parse sourcepkg. err: %w", err)
607			}
608	
609			return &models.Package{
610				Name:    fields[0],
611				Version: rpmPackageVersion(fields[1], fields[2], ""),
612				Release: fields[3],
613				Arch:    fields[4],
614				ModularityLabel: func() string {
615					if len(fields) == 7 && fields[6] != "(none)" {
616						return fields[6]
617					}
618					return ""
619				}(),
620			}, sp, nil
621		default:
622			return nil, nil, xerrors.Errorf("Failed to parse package line: %s", line)
623		}
624	}
