670	func rpmPackageVersion(epoch, version, release string) string {
671		if release != "" {
672			version += "-" + release
673		}
674		if epoch != "" && epoch != "0" && epoch != "(none)" {
675			version = epoch + ":" + version
676		}
677		return version
678	}
