680	// splitFileName returns a name, version, release, epoch, arch:
681	//
682	//	e.g.
683	//		foo-1.0-1.i386.rpm => foo, 1.0, 1, i386
684	//		1:bar-9-123a.ia64.rpm => bar, 9, 123a, 1, ia64
685	//
686	// https://github.com/rpm-software-management/yum/blob/043e869b08126c1b24e392f809c9f6871344c60d/rpmUtils/miscutils.py#L301
687	func splitFileName(filename string) (name, ver, rel, epoch, arch string, err error) {
688		invalid := func() (string, string, string, string, string, error) {
689			return "", "", "", "", "", xerrors.Errorf("unexpected file name. expected: %q, actual: %q", "<name>-<version>-<release>.<arch>.rpm", filename)
690		}
691		if !strings.HasSuffix(filename, ".rpm") {
692			return invalid()
693		}
694		basename := strings.TrimSuffix(filename, ".rpm")
695	
696		// Some source RPMs use "-src.rpm" in place of ".src.rpm".
697		var nvr string
698		if strings.HasSuffix(basename, "-src") {
699			arch, nvr = "src", strings.TrimSuffix(basename, "-src")
700		} else {
701			archIndex := strings.LastIndex(basename, ".")
702			if archIndex == -1 {
703				return invalid()
704			}
705			arch, nvr = basename[archIndex+1:], basename[:archIndex]
706		}
707		if arch == "" || strings.ContainsAny(arch, "-./\\ \t\r\n") {
708			return invalid()
709		}
710	
711		relIndex := strings.LastIndex(nvr, "-")
712		if relIndex == -1 {
713			return invalid()
714		}
715		rel = nvr[relIndex+1:]
716		nameVersion := nvr[:relIndex]
717		verIndex := strings.LastIndex(nameVersion, "-")
718		if verIndex == -1 {
719			return invalid()
720		}
721		name, ver = nameVersion[:verIndex], nameVersion[verIndex+1:]
722		if name == "" || ver == "" || strings.HasPrefix(name, "-") || strings.HasSuffix(name, "-") || strings.ContainsAny(name+ver+rel, "/\\ \t\r\n") || strings.ContainsAny(ver+rel, ":") {
723			return invalid()
724		}
725		if prefix, rest, hasEpoch := strings.Cut(name, ":"); hasEpoch {
726			if prefix == "" || rest == "" || strings.HasPrefix(rest, "-") || strings.HasSuffix(rest, "-") || strings.Trim(prefix, "0123456789") != "" || strings.Contains(rest, ":") {
727				return invalid()
728			}
729			epoch, name = prefix, rest
730		}
731		return name, ver, rel, epoch, arch, nil
732	}
